import{mountShell}from'../shared/shell.js?v=0.12.0';import{escapeHtml as e,readStore,writeStore,downloadText}from'../shared/utils.js?v=0.12.0';import{HORIZON,DEFAULTS,SCENARIOS,config,createRun,step,observation,simulate,metrics,restore,serialize,readings}from'./engine.js?v=0.12.0';
mountShell({active:'delay'});
const KEY='thinking-lab:delay:v1',root=document.querySelector('#app');
let stored=readStore(KEY,{}),settings=config(stored.settings),baseline=config(stored.baseline??{...DEFAULTS,lag:0}),manual;
try{manual=restore(stored.manual);}catch{manual=createRun(settings);}
let mode=stored.mode==='compare'?'compare':'play',command=Number.isFinite(stored.command)?Math.max(0,Math.min(12,stored.command)):manual.command,revealed=!!stored.revealed,scrub=Math.max(0,Math.min(HORIZON,Number(stored.scrub)||24)),timer=null,noticeTimer,dragging=false;
const round=v=>Number(v).toFixed(1),rule=()=>simulate(settings),reference=()=>simulate({...baseline,scenario:settings.scenario});
function say(text){const el=document.querySelector('#notice');el.textContent=text;el.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.classList.remove('show'),3000);}
function save(){const ok=writeStore(KEY,{settings,baseline,manual:serialize(manual),mode,command,revealed,scrub});const note=document.querySelector('.save-note');if(note)note.textContent=ok?'Saved in this browser. Export a copy to keep the experiment.':'Browser storage is unavailable. Export to keep this experiment.';}
function pause(){clearInterval(timer);timer=null;const b=document.querySelector('[data-action="run"]');if(b)b.textContent='Run';}
function tick(){if(manual.tick>=HORIZON){pause();revealed=true;render();return;}manual=step(manual,command);if(manual.tick>=HORIZON){pause();revealed=true;}updateDisplay();save();}
function changeCommand(next){command=Math.round(Math.max(0,Math.min(12,next))*10)/10;updateDisplay();save();}
function viewState(){if(mode==='play')return{state:manual,observed:observation(manual),row:manual.history.at(-1),showActual:revealed};const state=rule(),row=state.history[scrub];return{state,observed:state.history[Math.max(0,scrub-settings.lag)].level,row,showActual:true};}
function render(){const focus=document.activeElement?.id;
root.innerHTML=`<header class="intro"><div><p class="eyebrow">Model 04 · The delay between action and evidence</p><h1>Steering through delay</h1><p>Move the inflow lever. Keep the level near 50. Your instrument tells you what happened earlier.</p></div><button class="btn quiet" data-action="export">Export experiment ↗</button></header><div class="topbar"><div class="modes" role="group" aria-label="Experiment mode"><button class="btn ${mode==='play'?'active':''}" data-action="mode" data-mode="play" aria-pressed="${mode==='play'}">Try steering</button><button class="btn ${mode==='compare'?'active':''}" data-action="mode" data-mode="compare" aria-pressed="${mode==='compare'}">Compare feedback rules</button></div><span class="topbar-note">A fictional reservoir · target band 45–55</span></div>
<div class="layout"><section class="instrument"><div class="instrument-heading"><h2>${mode==='play'?'Your instrument says…':'Inspect the rule in motion'}</h2><span class="clock" id="clock"></span></div><div class="instrument-stage"><div class="level-column"><div class="readout"><b id="reading"></b><small id="reading-age"></small></div><div class="tank" role="img" aria-label="Observed reservoir level and target band"><div class="target-band"></div><div class="tank-fill" id="tank-fill"></div><span class="target-label">Target 50</span><div class="actual-level" id="actual-level"><span id="actual-label"></span></div></div><div class="tank-caption">0 empty · 100 full</div></div><div class="gate-column"><span class="gate-label">Inflow command</span><b class="gate-number" id="gate-number"></b><span class="gate-unit">units per tick</span><div class="gate-track" id="gate-track"><div class="gate-fill" id="gate-fill"></div><button class="gate-handle" id="gate-handle" role="slider" aria-label="Inflow command" aria-valuemin="0" aria-valuemax="12" aria-orientation="vertical" ${mode==='compare'?'disabled':''}>↕</button></div><div class="gate-buttons"><button class="btn small" data-action="less" aria-label="Reduce inflow by half a unit" ${mode==='compare'?'disabled':''}>−</button><button class="btn small" data-action="more" aria-label="Increase inflow by half a unit" ${mode==='compare'?'disabled':''}>+</button></div></div></div>
<p class="control-caption">${mode==='play'?'Drag the inflow lever, or use ↑ / ↓ when it is focused. Raise it, step a few ticks, and wait for the reading to catch up.':'Drag across the trace or scrub through the run. The rule chooses inflow from the observed level; the line labelled “Actual” shows the actual level at that moment.'}</p>
${mode==='play'?`<div class="run-controls"><button class="btn primary" data-action="run">Run</button><button class="btn" data-action="step">+1 tick</button><button class="btn" data-action="undo">Undo tick</button><button class="btn quiet" data-action="reset">New run</button></div><div class="reveal-control"><label><input type="checkbox" id="reveal" ${revealed?'checked':''}> Reveal actual level</label><span id="reveal-note">Learning view; this gives you extra information.</span></div>`:`<div class="scrub"><label for="scrub">Drag time backwards and forwards <output id="scrub-value"></output></label><input id="scrub" type="range" min="0" max="60" step="1" value="${scrub}"></div>`}</section>
<div class="right-column"><section class="trace"><h2>${mode==='play'?'The signal you are steering by':'Same system. Different feedback.'}</h2><p>${mode==='play'?'The observed trace is the information available at each tick. Reveal reality to compare.':'Both rules face the same withdrawal sequence and start at the same level.'}</p><div class="legend"><span><i></i>Observed</span><span class="actual" id="actual-legend"><i></i>Actual</span>${mode==='compare'?'<span class="baseline"><i></i>Pinned rule · actual</span>':''}</div><div id="chart" class="chart"></div><div id="metrics"></div></section>
<section class="settings"><h2>${mode==='play'?'Set up the next run':'Change the feedback loop'}</h2><p class="settings-intro">${mode==='play'?'These settings apply when you start a New run. The lever changes the current run immediately.':'Each edit replays the full run from tick 0. The pinned rule stays fixed; both face your selected pattern.'}</p><div class="settings-grid"><div class="setting"><label for="lag">Reporting lag <output id="lag-out">${settings.lag} ticks</output></label><input id="lag" data-setting="lag" type="range" min="0" max="12" step="1" value="${settings.lag}"><small>How old the level reading is.</small></div><div class="setting"><label for="response">Actuator response <output id="response-out">${Math.round(settings.response*100)}%</output></label><input id="response" data-setting="response" type="range" min=".1" max="1" step=".1" value="${settings.response}"><small>Gap to the commanded flow closed each tick.</small></div>${mode==='compare'?`<div class="setting"><label for="gain">Response strength <output id="gain-out">${settings.gain.toFixed(2)}</output></label><input id="gain" data-setting="gain" type="range" min="0" max="1.5" step=".05" value="${settings.gain}"><small>Extra inflow for each point below target.</small></div><div class="setting"><label for="review">Review every <output id="review-out">${settings.review} tick${settings.review===1?'':'s'}</output></label><input id="review" data-setting="review" type="range" min="1" max="8" step="1" value="${settings.review}"><small>Hold the last command between reviews.</small></div>`:''}<div class="setting full"><label for="scenario">Withdrawal pattern</label><select id="scenario">${Object.entries(SCENARIOS).map(([id,s])=>`<option value="${id}" ${settings.scenario===id?'selected':''}>${s.name}</option>`).join('')}</select></div></div>${mode==='compare'?`<div class="baseline-controls"><button class="btn small" data-action="pin">Pin this rule</button><button class="btn small quiet" data-action="baseline-reset">Restore zero-lag reference</button><span id="baseline-note"></span></div>`:''}<p class="comparison-note">${mode==='play'?'A fixed training pattern. Replaying it lets you learn its shape; this is not a blind comparison of skill.':'The rule aims for 50: inflow = 5 + strength × (50 − observed level), bounded between 0 and 12.'}</p></section></div></div>
<details class="assumptions"><summary>What is happening inside the model?</summary><div class="assumptions-grid"><div><p>A bounded reservoir has a target level of 50 and a useful band of 45–55. Withdrawal is external. Your commanded inflow passes through an actuator that closes a fraction of the gap each tick. Reporting lag hides the most recent levels.</p><p><code>flow[t] = flow[t−1] + response × (command − flow[t−1])</code><br><code>level[t] = level[t−1] + flow[t] − withdrawal[t]</code></p><p>Overflow is removed above 100; withdrawal that cannot be supplied is counted below 0. Initial level is 50 and initial flow is 5.</p></div><div><p>The comparison rule knows its old level reading and the nominal withdrawal of 5. It has no view of future withdrawal. The same pattern is used for both rules, and manual steering stays separate from automatic-rule comparisons.</p><p>These parameters are illustrative. There is no measurement noise, strategic response, integral controller or calibration to a real team, reservoir or market. A stronger response can help in one setting and oscillate in another.</p><p>Mean error and time in band refer to actual level. They stay hidden during manual steering until you reveal reality or finish. The complete equations are in <a href="engine.js">the engine</a>.</p></div></div></details><p class="save-note"></p>`;
bind();updateDisplay();if(focus)document.getElementById(focus)?.focus({preventScroll:true});save();}
function updateDisplay(){const v=viewState(),row=v.row,shownCommand=mode==='play'?command:row.command;
document.querySelector('#clock').textContent=`Tick ${row.tick} / ${HORIZON}`;document.querySelector('#reading').textContent=round(v.observed);document.querySelector('#reading-age').innerHTML=`Reading from<br>tick ${Math.max(0,row.tick-v.state.settings.lag)}`;document.querySelector('#tank-fill').style.height=v.observed+'%';document.querySelector('.tank').setAttribute('aria-label',`Observed level ${round(v.observed)}, target 50${v.showActual?', actual level '+round(row.level):''}`);document.querySelector('#actual-level').hidden=!v.showActual;document.querySelector('#actual-level').style.bottom=row.level+'%';document.querySelector('#actual-label').textContent=round(row.level)+' actual';document.querySelector('#gate-number').textContent=round(shownCommand);document.querySelector('#gate-fill').style.height=shownCommand/12*100+'%';const handle=document.querySelector('#gate-handle');handle.style.bottom=shownCommand/12*100+'%';handle.setAttribute('aria-valuenow',shownCommand);handle.setAttribute('aria-valuetext',`${round(shownCommand)} units per tick`);
document.querySelector('#actual-legend').hidden=!v.showActual;document.querySelector('#scrub-value')?.replaceChildren(`Tick ${scrub}`);if(mode==='play'){document.querySelector('[data-action="run"]').disabled=manual.tick>=HORIZON;document.querySelector('[data-action="run"]').textContent=timer?'Pause':'Run';document.querySelector('[data-action="step"]').disabled=manual.tick>=HORIZON;document.querySelector('[data-action="undo"]').disabled=manual.tick===0;document.querySelector('#reveal').checked=revealed;document.querySelector('#reveal-note').textContent=manual.tick>=HORIZON?'Run complete. Actual path revealed.':`Current run: ${manual.settings.lag}-tick reporting lag.`;}
if(mode==='compare')document.querySelector('#baseline-note').textContent=`Pinned: lag ${baseline.lag}, strength ${baseline.gain.toFixed(2)}, review ${baseline.review}, actuator ${Math.round(baseline.response*100)}%.`;
const m=metrics(v.state),b=mode==='compare'?metrics(reference()):null;document.querySelector('#metrics').innerHTML=!v.showActual?'<div class="withheld">Keep steering from the instrument. Reveal actual level to inspect error, overflow and the real path.</div>':`<div class="metrics"><div class="metric"><b>${round(m.meanError)}</b><span>Mean distance from 50</span>${b?`<small>Pinned: ${round(b.meanError)}</small>`:''}</div><div class="metric"><b>${Math.round(m.inBand*100)}%</b><span>Time in target band</span>${b?`<small>Pinned: ${Math.round(b.inBand*100)}%</small>`:''}</div><div class="metric"><b>${round(m.spill+m.unmet)}</b><span>Overflow + unmet withdrawal</span>${b?`<small>Pinned: ${round(b.spill+b.unmet)}</small>`:''}</div></div>`;drawChart(v);}
function drawChart(v=viewState()){const el=document.querySelector('#chart');if(!el)return;const w=Math.max(280,el.clientWidth),h=224,p={l:32,r:10,t:14,b:28},x=t=>p.l+t/HORIZON*(w-p.l-p.r),y=l=>h-p.b-l/100*(h-p.t-p.b);const path=rows=>rows.map((r,i)=>`${i?'L':'M'}${x(r.tick).toFixed(2)},${y(r.level).toFixed(2)}`).join(' ');const actual=v.state.history,seen=readings(v.state),base=mode==='compare'?reference().history:null;el.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Reservoir level over time, with delayed observation${v.showActual?' and actual level':''}"><rect x="${p.l}" y="${y(55)}" width="${w-p.l-p.r}" height="${y(45)-y(55)}" fill="var(--surface)"/>${[0,25,50,75,100].map(n=>`<line x1="${p.l}" x2="${w-p.r}" y1="${y(n)}" y2="${y(n)}" stroke="var(--line)"/><text x="${p.l-7}" y="${y(n)+4}" text-anchor="end" font-size="11" fill="var(--muted)">${n}</text>`).join('')}${[0,15,30,45,60].map(n=>`<text x="${x(n)}" y="${h-7}" text-anchor="middle" font-size="11" fill="var(--muted)">${n}</text>`).join('')}${base?`<path d="${path(base)}" fill="none" stroke="var(--line-strong)" stroke-width="2" stroke-dasharray="5 4"/>`:''}${v.showActual?`<path d="${path(actual)}" fill="none" stroke="var(--warn)" stroke-width="2.5"/>`:''}<path d="${path(seen)}" fill="none" stroke="var(--accent)" stroke-width="2.5"/>${mode==='compare'?`<line x1="${x(scrub)}" x2="${x(scrub)}" y1="${p.t}" y2="${h-p.b}" stroke="var(--line-strong)" stroke-dasharray="3 3"/><circle cx="${x(scrub)}" cy="${y(v.row.level)}" r="4" fill="var(--warn)"/>`:''}</svg>`;}
function bind(){const chart=document.querySelector('#chart');chart.classList.toggle('is-scrubbable',mode==='compare');let chartDrag=false;const scrubPointer=event=>{const box=chart.getBoundingClientRect();scrub=Math.max(0,Math.min(HORIZON,Math.round((event.clientX-box.left-32)/(box.width-42)*HORIZON)));document.querySelector('#scrub').value=scrub;updateDisplay();save();};chart.addEventListener('pointerdown',event=>{if(mode!=='compare'||event.button!==0)return;chartDrag=true;chart.setPointerCapture(event.pointerId);scrubPointer(event);});chart.addEventListener('pointermove',event=>{if(chartDrag){event.preventDefault();scrubPointer(event);}});chart.addEventListener('pointerup',()=>chartDrag=false);chart.addEventListener('pointercancel',()=>chartDrag=false);const handle=document.querySelector('#gate-handle'),track=document.querySelector('#gate-track');const pointer=event=>{const box=track.getBoundingClientRect();changeCommand((box.bottom-event.clientY)/box.height*12);};handle.addEventListener('pointerdown',event=>{if(mode!=='play'||event.button!==0)return;dragging=true;handle.setPointerCapture(event.pointerId);event.preventDefault();pointer(event);});handle.addEventListener('pointermove',event=>{if(dragging){event.preventDefault();pointer(event);}});handle.addEventListener('pointerup',()=>dragging=false);handle.addEventListener('pointercancel',()=>dragging=false);handle.addEventListener('keydown',event=>{const values={ArrowUp:command+.5,ArrowRight:command+.5,ArrowDown:command-.5,ArrowLeft:command-.5,Home:0,End:12,PageUp:command+2,PageDown:command-2};if(mode==='play'&&Object.hasOwn(values,event.key)){event.preventDefault();changeCommand(values[event.key]);}});}
root.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;switch(button.dataset.action){case'mode':pause();mode=button.dataset.mode;render();break;case'more':changeCommand(command+.5);break;case'less':changeCommand(command-.5);break;case'run':if(timer)pause();else{timer=setInterval(tick,430);updateDisplay();}break;case'step':pause();tick();break;case'undo':pause();manual=restore({settings:manual.settings,commands:manual.history.slice(1,-1).map(r=>r.command)});updateDisplay();save();break;case'reset':pause();manual=createRun(settings);command=5;revealed=false;render();say('New run with the selected settings. The training pattern repeats.');break;case'pin':baseline={...settings};updateDisplay();save();say('Current rule pinned. Change the loop to compare.');break;case'baseline-reset':baseline={...DEFAULTS,lag:0,scenario:settings.scenario};updateDisplay();save();break;case'export':exportRun();break;}});
root.addEventListener('input',event=>{const input=event.target;if(input.id==='scrub'){scrub=Number(input.value);updateDisplay();save();}else if(input.dataset.setting){settings=config({...settings,[input.dataset.setting]:Number(input.value)});for(const id of['lag','response','gain','review']){const out=document.querySelector('#'+id+'-out');if(out)out.textContent=id==='lag'?settings.lag+' ticks':id==='response'?Math.round(settings.response*100)+'%':id==='gain'?settings.gain.toFixed(2):settings.review+' ticks';}if(mode==='compare')updateDisplay();save();}else if(input.id==='reveal'){revealed=input.checked;updateDisplay();save();}});
root.addEventListener('change',event=>{if(event.target.id==='scenario'){settings=config({...settings,scenario:event.target.value});baseline.scenario=settings.scenario;if(mode==='compare')updateDisplay();save();}});
function exportRun(){const state=mode==='play'?manual:rule(),m=metrics(state),cfg=state.settings;let text=`# Steering through delay\n\nMode: ${mode==='play'?'Manual steering':'Feedback-rule comparison'}\nPattern: ${SCENARIOS[cfg.scenario].name}\nReporting lag: ${cfg.lag} ticks\nActuator response: ${cfg.response}\n${mode==='compare'?`Response strength: ${cfg.gain}\nReview interval: ${cfg.review} ticks\nPinned rule: ${JSON.stringify(baseline)}\n`:''}\nMean actual error: ${round(m.meanError)}\nTime in target band: ${Math.round(m.inBand*100)}%\nOverflow: ${round(m.spill)}\nUnmet withdrawal: ${round(m.unmet)}\n\n${mode==='play'&&!revealed?'Export includes actual hidden state for analysis.\n\n':''}| Tick | Observed | Actual | Command | Delivered inflow | Withdrawal |\n|---:|---:|---:|---:|---:|---:|\n`;const seen=readings(state);text+=state.history.map((r,i)=>`| ${r.tick} | ${round(seen[i].level)} | ${round(r.level)} | ${round(r.command)} | ${round(r.pump)} | ${round(r.withdrawal)} |`).join('\n');text+='\n\nIllustrative bounded-reservoir model. Fixed training patterns, no measurement noise or calibration to a real system. Automatic rules only use their delayed observation and nominal withdrawal.\n';downloadText('steering-through-delay.md',text,'text/markdown;charset=utf-8');say('Experiment exported. The file includes the actual trajectory.');}
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});addEventListener('pagehide',()=>{pause();save();});let resizeFrame;addEventListener('resize',()=>{cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>drawChart());});render();
